export class List {
    datatext = leaf("");
    items = new Items;
    map = new Map;
    async update() {
        const res = await fetch("https://www.jma.go.jp/bosai/quake/data/list.json");
        if (res.status != 200)
            return;
        const src_data = await res.json();
        const basetime = (new Date().getTime() / daytick) - 30;
        const map = new Map;
        for (const src of src_data) {
            const eid = src.eid;
            const iso = map.get(eid);
            if (!iso)
                map.set(src.eid, src);
            else if (src.ser > iso.ser)
                map.set(eid, src);
        }
        this.items.replace(Array.from(map, ([key, src]) => item(src, basetime)));
        // this.update_monitor ( data ) ;
    }
    update_monitor(data) {
        this.datatext.value = "";
        // this.datatext.value = JSON.stringify ( data , null , "\t" ) ;
    }
}
